import { describe, expect, it } from 'vitest';
import { domainOf, normalizeUrl, thumbOf } from '../src/cards/link';
import { addCol, addRow, MAX_COLS, normalizeRows, removeCol, removeRow } from '../src/cards/table';
import { nextState, progress, stateOf } from '../src/cards/todo';

describe('bağlantı', () => {
  it('adresi düzeltir, yalnızca http(s) kabul eder', () => {
    expect(normalizeUrl('example.com/a')).toBe('https://example.com/a');
    expect(normalizeUrl('  http://x.io ')).toBe('http://x.io/');
    expect(normalizeUrl('javascript:alert(1)')).toBeNull();
    expect(normalizeUrl('data:text/html,hi')).toBeNull();
    expect(normalizeUrl('')).toBeNull();
  });
  it('alan adı', () => {
    expect(domainOf('https://www.artstation.com/x')).toBe('artstation.com');
    expect(domainOf('bozuk')).toBe('');
  });
  it('YouTube ve görsel bağlantılarında küçük resim verir', () => {
    expect(thumbOf('https://www.youtube.com/watch?v=dQw4w9WgXcQ')).toBe('https://img.youtube.com/vi/dQw4w9WgXcQ/hqdefault.jpg');
    expect(thumbOf('https://youtu.be/dQw4w9WgXcQ?t=3')).toBe('https://img.youtube.com/vi/dQw4w9WgXcQ/hqdefault.jpg');
    expect(thumbOf('https://youtube.com/shorts/abcdefGHIJ1')).toBe('https://img.youtube.com/vi/abcdefGHIJ1/hqdefault.jpg');
    expect(thumbOf('https://cdn.site.com/art/ref.PNG')).toBe('https://cdn.site.com/art/ref.PNG');
    expect(thumbOf('https://example.com/page')).toBeNull();
  });
});

describe('tablo', () => {
  it('eksik hücreleri tamamlar ve varsayılan tablo verir', () => {
    expect(normalizeRows([['a', 'b'], ['c']])).toEqual([['a', 'b'], ['c', '']]);
    expect(normalizeRows(undefined)).toHaveLength(3);
  });
  it('satır / sütun ekler ve siler; başlık satırı ve son sütun korunur', () => {
    const r = normalizeRows([['A', 'B'], ['1', '2']]);
    addRow(r); expect(r).toEqual([['A', 'B'], ['1', '2'], ['', '']]);
    addCol(r); expect(r[0]).toEqual(['A', 'B', '']); expect(r[1]).toEqual(['1', '2', '']);
    removeRow(r, 0); expect(r).toHaveLength(3);
    removeRow(r, 2); expect(r).toHaveLength(2);
    removeCol(r, 0); removeCol(r, 0); removeCol(r, 0);
    expect(r[0]).toEqual(['']);
  });
  it(`en fazla ${MAX_COLS} sütun`, () => {
    const r = normalizeRows([Array(MAX_COLS).fill('x')]);
    addCol(r); expect(r[0]).toHaveLength(MAX_COLS);
  });
});

describe('yapılacaklar', () => {
  it('durum döngüsü: yapılacak → sürüyor → bitti → yapılacak; eski kayıtlar okunur', () => {
    expect(nextState('todo')).toBe('doing');
    expect(nextState('doing')).toBe('done');
    expect(nextState('done')).toBe('todo');
    expect(stateOf({ id: 'a', text: '', done: true })).toBe('done');
    expect(stateOf({ id: 'a', text: '', done: false })).toBe('todo');
  });
  it('ilerleme: biten tam, süren yarım birim', () => {
    const p = progress([{ id: '1', text: '', state: 'done' }, { id: '2', text: '', state: 'done' }, { id: '3', text: '', state: 'doing' }, { id: '4', text: '', state: 'todo' }]);
    expect(p).toMatchObject({ n: 4, done: 2, doing: 1, green: .5, yellow: .125 });
    expect(progress([])).toMatchObject({ green: 0, yellow: 0 });
  });
});

/** Projenin veri şeması. Kaydedilen JSON tam olarak bu tiplerden oluşur. */

export interface Point { x: number; y: number }
export interface Rect extends Point { w: number; h: number }
export type Vec = [number, number];

export type HAlign = 'left' | 'center' | 'right';
export type VAlign = 'top' | 'middle' | 'bottom';
export type ArrowHead = 'end' | 'start' | 'both' | 'none';

/** Kart türü kimliği: `cards/types.ts` içindeki kayıt defterinin anahtarı. */
export type CardTypeId = string;

export interface Card extends Rect {
  id: string;
  type: CardTypeId;
  text?: string;
  /** Kart (grupta başlık) rengi. */
  color: string;
  /** Yazı rengi; yoksa tema rengi. */
  tc?: string;
  /** Grubun içerik alanı rengi; yoksa başlık rengi. */
  bg?: string;
  /** Yazı boyutu; yoksa türün varsayılanı. */
  fs?: number;
  align?: HAlign;
  valign?: VAlign;
  /** Görsel kartı: data: URL. */
  src?: string;
  /** Bölüm kartı: içindeki sayfanın kimliği. */
  page?: string;
  /** Grup: başlık yüksekliği. */
  hh?: number;
  /** Bağlantı kartı: adres ve kısa not (başlık `text`te). */
  url?: string;
  desc?: string;
  /** Yapılacaklar kartı: maddeler (başlık `text`te). */
  items?: TodoItem[];
  /** Tablo kartı: hücreler; ilk satır başlık satırıdır (tablo adı `text`te). */
  rows?: string[][];
}

export type TodoState = 'todo' | 'doing' | 'done';
/** Yapılacaklar maddesi. `done` eski kayıtlardan kalır; yeni kayıtlar `state` kullanır. */
export interface TodoItem { id: string; text: string; state?: TodoState; done?: boolean }

export interface Arrow {
  id: string;
  /** Bağlı olduğu kartlar (yoksa serbest uç). */
  a?: string | null;
  b?: string | null;
  /** Serbest uçların konumu. */
  x1: number; y1: number; x2: number; y2: number;
  /** Eğri: orta noktaya göre kontrol noktası kayması. */
  bx?: number; by?: number;
  col?: string;
  w?: number;
  head?: ArrowHead;
  label?: string;
}

export interface View { x: number; y: number; z: number }

export interface Page {
  id: string;
  name: string;
  cards: Card[];
  arrows: Arrow[];
  v: View;
  parent?: string;
  base?: boolean;
}

export interface Palettes {
  color: string[];
  tc: string[];
  fs: number[];
  ac: string[];
  bg: string[];
}
export type PaletteKey = keyof Palettes;

export interface ProjectState {
  name: string;
  cur: number;
  pages: Page[];
  pal: Palettes;
}

import { COLORS } from '../core/config';
import type { Card, TodoItem, TodoState } from '../core/types';
import { trackPointer, uid } from '../core/utils';
import { CTL, h } from './dom';
import type { BodyContext, CardTypeDef } from './registry';

const focusItem = (id: string) => `.titem[data-id="${id}"] .ttext`;

/* ── saf yardımcılar (test edilir) ── */
export const stateOf = (it: TodoItem): TodoState => it.state ?? (it.done ? 'done' : 'todo');
/** Kutuya tıklayınca: yapılacak → sürüyor (sarı) → bitti (yeşil) → yapılacak. */
export const nextState = (s: TodoState): TodoState => s === 'todo' ? 'doing' : s === 'doing' ? 'done' : 'todo';
export const STATE_TIP: Record<TodoState, string> = { todo: 'Yapılacak · tıkla: başladım', doing: 'Sürüyor · tıkla: bitti', done: 'Bitti · tıkla: sıfırla' };
/** İlerleme çubuğu oranları (0..1): her biten madde tam, her süren madde yarım birim. */
export function progress(items: TodoItem[]) {
  const n = items.length, done = items.filter(i => stateOf(i) === 'done').length, doing = items.filter(i => stateOf(i) === 'doing').length;
  return { n, done, doing, green: n ? done / n : 0, yellow: n ? doing * .5 / n : 0 };
}

/** Kartın son çizilen ilerleme oranları: kart yeniden kurulunca çubuk eski boyundan yenisine kayarak gelir. */
const lastBar = new Map<string, { green: number; yellow: number }>();

function renderBody(body: HTMLElement, c: Card, ctx: BodyContext) {
  const items = (c.items ??= []);
  const changed = (focus?: string) => { ctx.commit(); ctx.rerender(c, focus); };
  const addAfter = (i: number) => { const it: TodoItem = { id: uid(), text: '', state: 'todo' }; items.splice(i + 1, 0, it); changed(focusItem(it.id)); };
  const p = progress(items);

  const list = h('div', { class: 'tlist' });
  items.forEach((it, i) => {
    const text = h('input', {
      class: `ttext ${CTL}`, value: it.text, placeholder: 'Madde…',
      on: {
        input: () => { it.text = text.value; ctx.commit(); },
        keydown: e => {
          if (e.key === 'Enter') { e.preventDefault(); addAfter(i); }
          else if (e.key === 'Backspace' && !text.value) { e.preventDefault(); items.splice(i, 1); changed(items[i - 1] ? focusItem(items[i - 1].id) : '.rtitle'); }
          else if (e.key === 'ArrowUp' && items[i - 1]) { e.preventDefault(); (list.querySelector(focusItem(items[i - 1].id)) as HTMLElement).focus(); }
          else if (e.key === 'ArrowDown' && items[i + 1]) { e.preventDefault(); (list.querySelector(focusItem(items[i + 1].id)) as HTMLElement).focus(); }
        },
      },
    });
    const st = stateOf(it);
    const row = h('div', { class: `titem ${st}`, 'data-id': it.id },
      h('span', { class: 'tgrip', title: 'Sürükleyerek sırala', text: '⋮⋮', on: { pointerdown: e => reorder(e, i) } }),
      h('button', { class: `tcheck ${st} ${CTL}`, title: STATE_TIP[st], tabIndex: -1, on: { click: () => { it.state = nextState(st); delete it.done; changed(); } } }),
      text,
      h('button', { class: `tdel ${CTL}`, text: '✕', title: 'Maddeyi sil', tabIndex: -1, on: { click: () => { items.splice(i, 1); changed(); } } }),
    );
    list.appendChild(row);
  });

  /** Tutamaçtan sürükleyerek sıralama: satır imleci izler, bırakınca yeni sıra kaydedilir. */
  function reorder(ev: PointerEvent, from: number) {
    ev.stopPropagation(); ev.preventDefault();
    const rows = [...list.children] as HTMLElement[], row = rows[from];
    let to = from;
    trackPointer(ev, {
      threshold: 3,
      onStart: () => row.classList.add('drag'),
      onMove: (_dx, _dy, m) => {
        // Yeni sıra: imlecin, ortasının altında kaldığı diğer satır sayısı.
        const others = rows.filter(r => r !== row);
        to = others.filter(r => { const q = r.getBoundingClientRect(); return m.clientY > q.top + q.height / 2; }).length;
        list.insertBefore(row, others[to] ?? null);
      },
      onEnd: moved => {
        row.classList.remove('drag');
        if (!moved || to === from) return;
        const [it] = items.splice(from, 1); items.splice(to, 0, it); changed();
      },
    });
  }

  // İlerleme: yeşil (biten) + sarı (süren, yarım boy). Önceki oranlardan yenisine hızlıca kayar.
  const green = h('i', { class: 'pg' }), yellow = h('i', { class: 'py' });
  const bar = h('div', { class: 'tprog', title: `${p.done} bitti · ${p.doing} sürüyor · ${p.n - p.done - p.doing} bekliyor` },
    h('b', {}, green, yellow), h('span', { text: `${p.done}/${p.n}` }));
  const prev = lastBar.get(c.id), pct = (v: number) => v * 100 + '%';
  const paint = (q: { green: number; yellow: number }) => { green.style.width = pct(q.green); yellow.style.width = pct(q.yellow); };
  if (prev && (prev.green !== p.green || prev.yellow !== p.yellow)) {
    paint(prev);
    requestAnimationFrame(() => requestAnimationFrame(() => { bar.classList.add('anim'); paint(p); }));
  } else paint(p);
  lastBar.set(c.id, { green: p.green, yellow: p.yellow });

  body.classList.add('rich', 'todob');
  body.append(
    h('input', { class: `rtitle ${CTL}`, value: c.text ?? '', placeholder: 'Liste başlığı', on: { input: e => { c.text = (e.target as HTMLInputElement).value; ctx.commit(); }, keydown: e => { if (e.key === 'Enter') { e.preventDefault(); addAfter(-1); } } } }),
    bar,
    list,
    h('button', { class: `tadd ${CTL}`, text: '+ Madde ekle', on: { click: () => addAfter(items.length - 1) } }),
  );
}

export const TODO: CardTypeDef = {
  label: 'Yapılacaklar', size: [264, 216], color: COLORS[2], text: false,
  init(c) { c.items = [{ id: uid(), text: '', state: 'todo' }]; },
  renderBody,
  editOnClick: () => false,
};

import { COLORS } from '../core/config';
import type { Card } from '../core/types';
import { CTL, h } from './dom';
import type { BodyContext, CardTypeDef } from './registry';

/* ── saf yardımcılar (test edilir) ── */
export const MAX_COLS = 12;
/** Tablonun dikdörtgen olmasını garanti eder (eksik hücreleri boş dizeyle doldurur). */
export function normalizeRows(rows: string[][] | undefined): string[][] {
  const r = rows?.length ? rows : [['Ad', 'Değer', 'Not'], ['', '', ''], ['', '', '']];
  const w = Math.max(1, ...r.map(x => x.length));
  return r.map(x => Array.from({ length: w }, (_, i) => x[i] ?? ''));
}
export const addRow = (rows: string[][], at = rows.length) => { rows.splice(at, 0, rows[0].map(() => '')); };
export const addCol = (rows: string[][], at = rows[0].length) => { if (rows[0].length < MAX_COLS) rows.forEach(r => r.splice(at, 0, '')); };
/** Başlık satırı ve son sütun silinmez. */
export const removeRow = (rows: string[][], i: number) => { if (i > 0 && rows.length > 1) rows.splice(i, 1); };
export const removeCol = (rows: string[][], j: number) => { if (rows[0].length > 1) rows.forEach(r => r.splice(j, 1)); };

const cell = (i: number, j: number) => `[data-c="${i}:${j}"]`;

function renderBody(body: HTMLElement, c: Card, ctx: BodyContext) {
  const rows = (c.rows = normalizeRows(c.rows)), cols = rows[0].length;
  const changed = (focus?: string) => { ctx.commit(); ctx.rerender(c, focus); };
  const focus = (i: number, j: number) => (body.querySelector(cell(i, j)) as HTMLInputElement | null)?.focus();

  const table = h('table', { class: 'tbl' });
  rows.forEach((r, i) => {
    const tr = h(i === 0 ? 'thead' : 'tr', {});
    const line = i === 0 ? tr.appendChild(h('tr', {})) : tr;
    r.forEach((v, j) => {
      const inp = h('input', {
        class: CTL, value: v, 'data-c': `${i}:${j}`, placeholder: i === 0 ? 'Başlık' : '',
        on: {
          input: () => { rows[i][j] = inp.value; ctx.commit(); },
          keydown: e => {
            // Enter: aşağıdaki hücre (son satırdaysa yeni satır açılır). Yukarı/aşağı ok: satırlar arasında gez.
            if (e.key === 'Enter') { e.preventDefault(); if (i + 1 < rows.length) focus(i + 1, j); else { addRow(rows); changed(cell(i + 1, j)); } }
            else if (e.key === 'ArrowDown' && i + 1 < rows.length) { e.preventDefault(); focus(i + 1, j); }
            else if (e.key === 'ArrowUp' && i > 0) { e.preventDefault(); focus(i - 1, j); }
          },
        },
      });
      const td = h(i === 0 ? 'th' : 'td', {}, inp);
      if (i === 0 && cols > 1) td.appendChild(h('button', { class: `xcol ${CTL}`, text: '✕', title: 'Sütunu sil', tabIndex: -1, on: { click: () => { removeCol(rows, j); changed(); } } }));
      line.appendChild(td);
    });
    if (i > 0) line.appendChild(h('td', { class: 'xcell' }, h('button', { class: `xrow ${CTL}`, text: '✕', title: 'Satırı sil', tabIndex: -1, on: { click: () => { removeRow(rows, i); changed(); } } })));
    // Başlık satırının sonundaki yeşil +: en sağa yeni sütun ekler (üzerine gelince görünür).
    else line.appendChild(h('th', { class: 'xcell' }, cols < MAX_COLS
      ? h('button', { class: `addcol ${CTL}`, text: '+', title: 'Sütun ekle', tabIndex: -1, on: { click: () => { addCol(rows); changed(cell(0, cols)); } } })
      : null));
    table.appendChild(tr);
  });
  // Tablonun altındaki yeşil "+ Satır": en alta yeni satır ekler (tablonun üzerine gelince görünür).
  table.appendChild(h('tr', { class: 'addline' }, h('td', { colSpan: cols },
    h('button', { class: `addrow ${CTL}`, text: '+ Satır', title: 'Satır ekle', tabIndex: -1, on: { click: () => { addRow(rows); changed(cell(rows.length - 1, 0)); } } }))));

  body.classList.add('rich', 'tableb');
  body.append(
    h('input', { class: `rtitle ${CTL}`, value: c.text ?? '', placeholder: 'Tablo adı', on: { input: e => { c.text = (e.target as HTMLInputElement).value; ctx.commit(); } } }),
    h('div', { class: 'twrap' }, table),
  );
}

export const TABLE: CardTypeDef = {
  label: 'Tablo', size: [384, 216], color: COLORS[5], text: false,
  init(c) { c.rows = normalizeRows(undefined); },
  renderBody,
  editOnClick: () => false,
};

import { ARROW_COLOR } from '../core/config';
import { arrowEnds, arrowGeometry } from '../core/geometry';
import type { Arrow, Card } from '../core/types';
import { selection, store } from './context';
import { dom } from './dom';

type Parts = Record<'ln' | 'hs' | 'he' | 'tp' | 'hit' | 'halo' | 'lab' | 'lt' | 'ht' | 'tl' | 'hda' | 'hdb' | 'bd' | 'del', SVGElement>;
type ArrowEl = SVGGElement & { _r: Parts };

/** Okların SVG karşılıkları: anahtarlı DOM, kısmi güncelleme. */
export class ArrowLayer {
  private els = new Map<string, ArrowEl>();
  activeId: string | null = null;

  private create(ar: Arrow) {
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g') as ArrowEl;
    g.setAttribute('class', 'arw'); g.dataset.id = ar.id;
    g.innerHTML = '<path class="ln"/><path class="hh"/><path class="hh"/><path class="tp"/>'
      + '<path class="hit" data-tip="Ok|Sürükleyerek taşı. Uçlarından bağla, ortasından eğ. Tıkla: özelliklerini aç."/>'
      + '<text class="alabh"><textPath startOffset="50%"></textPath></text><text class="alab" data-tip="Etiket|Çift tıkla: düzenle."><textPath startOffset="50%"></textPath></text><circle class="tl" r="4"/>'
      + '<circle class="hd" data-e="a" r="9"/><circle class="hd" data-e="b" r="9"/>'
      + '<circle class="bd" data-bend="1" data-tip="Okun ortası|Sürükleyerek oku eğ. Çift tıkla: düzleştir." r="7"/>'
      + '<g class="del" data-del="1" data-tip="Oku sil"><circle r="9"/><path d="M-3.5-3.5L3.5 3.5M3.5-3.5L-3.5 3.5"/></g>';
    const [ln, hs, he, tp, hit, halo, lab, tl, hda, hdb, bd, del] = [...g.children] as SVGElement[];
    const lt = lab.firstElementChild as SVGElement, ht = halo.firstElementChild as SVGElement;
    tp.id = 'tp-' + ar.id; lt.setAttribute('href', '#' + tp.id); ht.setAttribute('href', '#' + tp.id);
    g._r = { ln, hs, he, tp, hit, halo, lab, lt, ht, tl, hda, hdb, bd, del };
    dom.linkLayer.appendChild(g); this.els.set(ar.id, g);
    return g;
  }
  update(ar: Arrow, cardMap: Map<string, Card> = store.cardMap()) {
    const g = this.els.get(ar.id) ?? this.create(ar), r = g._r;
    const { p1, p2, C } = arrowEnds(ar, cardMap), col = ar.col || ARROW_COLOR, w = ar.w || 2;
    const s = arrowGeometry(p1, p2, C, w, ar.head || 'end');
    g.style.color = col;   // tutamaçlar ve seçim parıltısı okun renginde (CSS: currentColor)
    r.ln.setAttribute('d', s.line); r.ln.style.stroke = col; r.ln.style.strokeWidth = String(w); r.hit.setAttribute('d', s.line);
    for (const [el, d] of [[r.hs, s.startHead], [r.he, s.endHead]] as const) { el.style.display = d ? '' : 'none'; if (d) { el.setAttribute('d', d); el.style.fill = col; } }
    const label = (ar.label || '').trim();
    r.lab.style.display = r.halo.style.display = label ? '' : 'none';
    if (label) {
      r.tp.setAttribute('d', s.labelPath);
      if (r.lt.textContent !== label) { r.lt.textContent = label; r.ht.textContent = label; }
      const size = Math.max(13, w + 5) + 'px';
      Object.assign(r.lab.style, { fill: col, fontSize: size });
      Object.assign(r.halo.style, { fontSize: size, strokeWidth: (w + 8) + 'px' });   // kalın çizgide de okunsun diye puntosu okla büyür
    }
    const tip = (on: unknown) => on ? 'Bağlı uç|Sürükle: bağı koparır ya da başka karta taşır.' : 'Ok ucu|Sürükleyip bir karta bırak; karta bağlanır.';
    r.tl.setAttribute('cx', String(p1[0])); r.tl.setAttribute('cy', String(p1[1])); r.tl.classList.toggle('on', !!ar.a);
    for (const [el, p, on] of [[r.hda, p1, ar.a], [r.hdb, p2, ar.b]] as const) {
      el.setAttribute('cx', String(p[0])); el.setAttribute('cy', String(p[1])); el.classList.toggle('on', !!on); el.dataset.tip = tip(on);
    }
    r.bd.setAttribute('cx', String(s.mid[0])); r.bd.setAttribute('cy', String(s.mid[1]));
    r.del.setAttribute('transform', `translate(${s.delAt[0]} ${s.delAt[1]})`);
    g.classList.toggle('act', ar.id === this.activeId); g.classList.toggle('sel', selection.has(ar.id));
  }
  updateMany(list: Arrow[]) { const m = store.cardMap(); list.forEach(a => this.update(a, m)); }
  /** Sayfadaki oklarla DOM'u eşitler (eksik olanı kurar, fazla olanı siler). */
  sync() {
    const list = store.page.arrows, ids = new Set(list.map(a => a.id));
    this.els.forEach((g, id) => { if (!ids.has(id)) { g.remove(); this.els.delete(id); } });
    this.updateMany(list);
  }
  setSelected(prev: Set<string>, next: Set<string>) {
    for (const id of new Set([...prev, ...next])) this.els.get(id)?.classList.toggle('sel', next.has(id));
  }
}
export const arrows = new ArrowLayer();
